package com.kuaixietech.integration;
import com.kuaixietech.security.DomainAccessGuard;
import jakarta.validation.constraints.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.kuaixietech.integration.IntegrationCatalog.*;
@Service
public class IntegrationConfiguration {
 private com.kuaixietech.coupler.CouplerService coupler;
 @org.springframework.beans.factory.annotation.Autowired public void couplerRouting(com.kuaixietech.coupler.CouplerService coupler){this.coupler=coupler;}
 private final JdbcTemplate db;private final DomainAccessGuard guard;private final IntegrationCipher cipher;private final IntegrationHttp http;
 public IntegrationConfiguration(JdbcTemplate db,DomainAccessGuard guard,IntegrationCipher cipher,IntegrationHttp http){this.db=db;this.guard=guard;this.cipher=cipher;this.http=http;}
 public record Input(boolean enabled,@Size(max=200) String remark,@NotNull @Size(max=30) Map<@NotBlank String,@NotNull @Size(max=16000) String> values,@NotNull @Size(max=30) List<String> clearFields){}
 private String scope(String v,String p,String f){return v+"/"+p+"/"+f;}
 private List<Map<String,Object>> fields(String v,String p){return db.queryForList("SELECT field_key,field_cipher FROM t_integration_secrets WHERE vendor=? AND product=?",v,p);}
 private String resolve(String value){if(!value.startsWith("env:"))return value;String name=value.substring(4);if(!name.matches("[A-Z][A-Z0-9_]{2,99}"))throw new IllegalStateException("INTEGRATION_ENV_REFERENCE_INVALID");String actual=System.getenv(name);if(actual==null||actual.isBlank())throw new IllegalStateException("INTEGRATION_ENV_REFERENCE_MISSING");return actual;}
 /** Trusted server-side use only. A disabled/missing record is different from an unreadable enabled configuration. */
 public boolean exists(String vendor,String product){if(coupler!=null&&!vendor.equals("credentials")&&coupler.managed(vendor,product))return true;return !db.queryForList("SELECT enabled FROM t_integration_settings WHERE vendor=? AND product=?",vendor,product).isEmpty();}
 public Map<String,String> runtime(String vendor,String product){if(coupler!=null&&!vendor.equals("credentials")){var routing=coupler.legacyNewCall(vendor,product);if(routing.managed())return routing.values();}return legacyLiveRuntime(vendor,product);}
 public Map<String,String> historicalLiveRuntime(String vendor,String product,long revision){if(revision<=0)return legacyLiveRuntime(vendor,product);if(coupler==null)throw new IllegalStateException("COUPLER_HISTORICAL_RESOLVER_UNAVAILABLE");var result=coupler.historicalLive(vendor,product,revision);if(!result.managed()||result.values()==null)throw new IllegalStateException("COUPLER_HISTORICAL_REVISION_MISSING");return result.values();}
 public Map<String,String> legacyLiveRuntime(String vendor,String product){var definition=product(vendor,product);var settings=db.queryForList("SELECT enabled FROM t_integration_settings WHERE vendor=? AND product=?",vendor,product);if(settings.isEmpty()||!truth(settings.getFirst().get("enabled")))return null;var result=new HashMap<String,String>();Set<String> allowed=new HashSet<>();definition.fields().forEach(f->allowed.add(f.key()));for(var field:fields(vendor,product)){String name=field.get("field_key").toString();if(allowed.contains(name))result.put(name,resolve(cipher.open(scope(vendor,product,name),field.get("field_cipher").toString())));}validate(definition,result,true);return Map.copyOf(result);}
 private boolean truth(Object value){return Boolean.TRUE.equals(value)||"1".equals(String.valueOf(value));}
 public Map<String,Object> catalog(){guard.requireAdmin();var settings=db.queryForList("SELECT vendor,product,enabled,remark,updated_by,updated_at FROM t_integration_settings");var products=new ArrayList<Map<String,Object>>();var definitions=new ArrayList<>(all());for(var state:settings)if("credentials".equals(state.get("vendor")))try{definitions.add(credentialBundle(state.get("product").toString()));}catch(IllegalArgumentException ignored){}for(var def:definitions){var item=new LinkedHashMap<String,Object>();item.put("vendor",def.vendor());item.put("code",def.code());item.put("category",def.category());item.put("mode",def.mode());item.put("docs",def.docs());var state=settings.stream().filter(s->def.vendor().equals(s.get("vendor"))&&def.code().equals(s.get("product"))).findFirst().orElse(Map.of());item.put("enabled",truth(state.get("enabled")));item.put("remark",Objects.toString(state.get("remark"),""));item.put("updatedAt",Objects.toString(state.get("updated_at"),""));var saved=fields(def.vendor(),def.code());var inputs=new ArrayList<Map<String,Object>>();for(var f:def.fields()){var value=new LinkedHashMap<String,Object>();value.put("key",f.key());value.put("secret",f.secret());value.put("required",f.required());var encrypted=saved.stream().filter(s->f.key().equals(s.get("field_key"))).findFirst();value.put("configured",encrypted.isPresent());String status="missing";if(encrypted.isPresent()){try{String plain=cipher.open(scope(def.vendor(),def.code(),f.key()),encrypted.get().get("field_cipher").toString());status="stored";if(!f.secret())value.put("value",plain);}catch(RuntimeException e){status="unreadable";}}value.put("status",status);inputs.add(value);}item.put("fields",inputs);products.add(item);}return Map.of("nativeDeliveryManaged",settings.stream().anyMatch(s->("aliyun".equals(s.get("vendor"))&&(Set.of("sms","directmail").contains(s.get("product"))))||("tencent".equals(s.get("vendor"))&&"sms".equals(s.get("product")))),"encryptionReady",cipher.ready(),"products",products,"specialized",List.of("payments","insurance"));}
 @Transactional public Map<String,String> save(String vendor,String code,Input input){String actor=guard.requireAdmin();var def=product(vendor,code);if(!cipher.ready())throw new IllegalStateException("INTEGRATION_ENCRYPTION_KEY_REQUIRED");var known=new HashMap<String,Field>();def.fields().forEach(f->known.put(f.key(),f));for(String key:input.values().keySet())if(!known.containsKey(key))throw new IllegalArgumentException("INTEGRATION_UNKNOWN_FIELD");for(String key:input.clearFields())if(!known.containsKey(key)||input.values().containsKey(key))throw new IllegalArgumentException("INTEGRATION_UNKNOWN_FIELD");
  // Seed metadata only for explicit catalog entries, preserving existing business configuration and ciphertext.
  db.update("INSERT IGNORE INTO t_integration_vendors(code,name) VALUES(?,?)",vendor,vendor);
  db.update("INSERT IGNORE INTO t_integration_products(vendor,code,name,category) VALUES(?,?,?,?)",vendor,code,code,def.category());
  for(var f:def.fields())db.update("INSERT IGNORE INTO t_integration_product_fields(vendor,product,field_key,label,secret) VALUES(?,?,?,?,?)",vendor,code,f.key(),f.key(),f.secret());
  // Every SMS update locks both known settings in the same order before checking exclusivity.
  if(def.category().equals("sms")){for(String v:List.of("aliyun","tencent"))db.update("INSERT IGNORE INTO t_integration_settings(vendor,product,enabled) VALUES(?,'sms',0)",v);db.queryForList("SELECT vendor,product,enabled FROM t_integration_settings WHERE product='sms' AND vendor IN('aliyun','tencent') ORDER BY vendor FOR UPDATE");}
  else db.update("INSERT IGNORE INTO t_integration_settings(vendor,product,enabled) VALUES(?,?,0)",vendor,code);
  db.queryForList("SELECT enabled FROM t_integration_settings WHERE vendor=? AND product=? FOR UPDATE",vendor,code);
  var values=new HashMap<String,String>();for(var saved:fields(vendor,code)){String name=saved.get("field_key").toString();if(known.containsKey(name)&&!input.clearFields().contains(name)&&!input.values().containsKey(name))try{values.put(name,cipher.open(scope(vendor,code,name),saved.get("field_cipher").toString()));}catch(RuntimeException e){if(input.enabled())throw e;}}
  values.putAll(input.values());input.clearFields().forEach(values::remove);validate(def,values,input.enabled());
  if(input.enabled()&&def.category().equals("sms")&&!db.queryForList("SELECT vendor FROM t_integration_settings WHERE product='sms' AND vendor IN('aliyun','tencent') AND vendor<>? AND enabled=1 FOR UPDATE",vendor).isEmpty())throw new IllegalArgumentException("INTEGRATION_SMS_PROVIDER_ALREADY_ENABLED");
  for(var entry:input.values().entrySet())db.update("INSERT INTO t_integration_secrets(vendor,product,field_key,field_cipher) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE field_cipher=VALUES(field_cipher)",vendor,code,entry.getKey(),cipher.seal(scope(vendor,code,entry.getKey()),entry.getValue()));
  for(String key:input.clearFields())db.update("DELETE FROM t_integration_secrets WHERE vendor=? AND product=? AND field_key=?",vendor,code,key);
  db.update("UPDATE t_integration_settings SET enabled=?,remark=?,updated_by=? WHERE vendor=? AND product=?",input.enabled(),input.remark(),actor,vendor,code);
  db.update("INSERT INTO t_admin_logs(id,operator_id,action,target_type,target_id,detail) VALUES(?,?,'integration_configuration','integration',?,?)",UUID.randomUUID().toString(),actor,vendor+"/"+code,"Configuration updated; values excluded");return Map.of("status","saved");
 }
 private void validate(Product def,Map<String,String> values,boolean enabled){if(def.vendor().equals("platform")&&enabled&&!Set.of("aliyun","tencent").contains(values.get("vendor")))throw new IllegalArgumentException("UPLOAD_VENDOR_UNSUPPORTED");if(enabled&&def.mode().equals("reference_only"))throw new IllegalArgumentException("INTEGRATION_ADAPTER_NOT_IMPLEMENTED");for(var field:def.fields())if(enabled&&field.required()&&(values.get(field.key())==null||resolve(values.get(field.key())).isBlank()))throw new IllegalArgumentException("INTEGRATION_REQUIRED_FIELD");if(values.containsKey("url")&&!values.get("url").isBlank()){var u=http.endpoint(values.get("url"),false);if(u.getRawQuery()!=null)throw new IllegalArgumentException("INTEGRATION_ENDPOINT_REJECTED");}if(values.containsKey("timeout_seconds")){int seconds=Integer.parseInt(values.get("timeout_seconds"));if(seconds<1||seconds>30)throw new IllegalArgumentException("INTEGRATION_TIMEOUT_INVALID");}}
}
